from common import *
R = []
def B(bid, name, author, year, definition, implication, check, conf='high', sub='Cognitive bias'):
    R.append(C('bias.' + bid, name, author, year, definition, implication, check, 'screen / flow', '', f'{author} ({year}).', 'Cognitive biases & behavioral effects', sub,
               conf=conf, source_set='Curated: cognitive biases & behavioral effects', sev='minor'))
B('availability', 'Availability heuristic', 'A. Tversky & D. Kahneman', 1973, 'People judge frequency or likelihood by how easily examples come to mind.', 'Vivid testimonials and recent events skew risk perception; present base rates alongside stories.', 'Are risk and frequency claims supported by numbers, not only vivid anecdotes?')
B('representativeness', 'Representativeness heuristic', 'D. Kahneman & A. Tversky', 1972, 'People judge probability by similarity to a prototype, neglecting base rates.', 'Users judge legitimacy by resemblance to familiar brands; consistent, conventional design signals legitimacy (and phishing exploits this).', 'Does the product look consistent with its own brand across all touchpoints so users can spot impostors?')
B('confirmation', 'Confirmation bias', 'P. C. Wason', 1960, 'Tendency to search for, interpret and remember information that confirms prior beliefs.', 'Researchers and stakeholders over-weight findings that confirm their designs; use structured analysis and disconfirming questions.', 'Were findings analyzed against pre-set criteria, including evidence against the team’s hypothesis?', sub='Research bias')
B('status-quo', 'Status quo bias', 'W. Samuelson & R. Zeckhauser', 1988, 'Preference for the current state of affairs; changes are perceived as losses.', 'Users resist redesigns and stick with defaults; migrate gradually and explain benefits.', 'Do redesigns preserve familiar paths or explain changes?')
B('sunk-cost', 'Sunk cost fallacy', 'H. Arkes & C. Blumer', 1985, 'Continuing an endeavor because of previously invested resources rather than future value.', 'Long forms and onboarding create commitment; exploiting it to retain users (e.g., hard-to-cancel after long setup) is manipulative.', 'Are cancel and exit options equally easy regardless of how much the user has invested?')
B('endowment', 'Endowment effect', 'R. Thaler', 1980, 'People value things more once they own them.', 'Free trials and customization create ownership feelings; be transparent about what happens at trial end.', 'Is trial-to-paid conversion transparent with advance reminders?')
B('bandwagon', 'Bandwagon effect / social proof', 'Classic social psychology (Asch 1951; Cialdini 1984)', '1951/1984', 'People adopt beliefs or behaviors because many others do.', 'Ratings, reviews and usage counts influence decisions; they must be genuine and current.', 'Are social proof claims (counts, reviews, "X people viewing") genuine and verifiable?')
B('authority', 'Authority bias', 'S. Milgram', 1963, 'Tendency to attribute greater accuracy to the opinion of an authority figure.', 'Expert endorsements and certifications raise trust; fake badges are deceptive.', 'Are trust badges, certifications and endorsements real and linked to verification?')
B('scarcity', 'Scarcity effect', 'S. Worchel, J. Lee & A. Adewole', 1975, 'Items perceived as scarce are perceived as more valuable.', 'Low-stock and limited-time messages drive urgency; fake scarcity is a deceptive pattern and illegal in many jurisdictions.', 'Are scarcity and urgency messages accurate and based on real inventory/time limits?')
B('reciprocity', 'Reciprocity', 'A. Gouldner; R. Cialdini', '1960/1984', 'People feel obliged to return favors.', 'Giving value first (free tools, content) before asking for signup builds goodwill.', 'Does the product give value before asking for personal information or payment?')
B('commitment-consistency', 'Commitment and consistency', 'J. Freedman & S. Fraser (foot-in-the-door)', 1966, 'After a small commitment, people are more likely to agree to larger related requests.', 'Progressive engagement (small first step) increases completion; escalating commitments must stay honest.', 'Do flows start with low-commitment steps and avoid bait-and-switch escalation?')
B('foot-in-door', 'Foot-in-the-door technique', 'J. Freedman & S. Fraser', 1966, 'Agreeing to a small request increases likelihood of agreeing to a larger one.', 'Start with easy micro-commitments (e.g., one question) in onboarding.', 'Is the first step of signup/onboarding small and easy?')
B('door-in-face', 'Door-in-the-face technique', 'R. Cialdini et al.', 1975, 'A large request refused first makes a subsequent smaller request more likely to be accepted.', 'Retention offers after a cancel request use this; acceptable if the user can still cancel easily.', 'After a cancel request, can users still complete cancellation in one clear step?')
B('loss-aversion', 'Loss aversion', 'D. Kahneman & A. Tversky', 1979, 'Losses are felt about twice as strongly as equivalent gains.', 'Loss-framed messages motivate (e.g., "don’t lose your progress"), but shaming and threats are manipulative.', 'Are loss-framed messages factual and free of guilt or shaming?')
B('framing', 'Framing effect', 'A. Tversky & D. Kahneman', 1981, 'Decisions change based on how equivalent information is presented.', 'Consent and pricing language must be neutral and clear.', 'Are consequential options framed neutrally?')
B('anchoring', 'Anchoring bias', 'A. Tversky & D. Kahneman', 1974, 'Over-reliance on the first piece of information.', 'First price shown anchors value; genuine reference prices only.', 'Are reference/strikethrough prices genuine?')
B('decoy', 'Decoy effect', 'J. Huber, J. Payne & C. Puto', 1982, 'An inferior option changes preference between two others.', 'Pricing tables often use decoys; ensure each tier serves real needs.', 'Does each pricing tier serve a real segment?')
B('default', 'Default bias', 'E. Johnson & D. Goldstein', 2003, 'People tend to accept pre-set options.', 'Defaults must favor users; never pre-check consent or paid add-ons.', 'Are any consent, marketing or paid options pre-selected?')
B('choice-overload', 'Choice overload / paradox of choice', 'S. Iyengar & M. Lepper; B. Schwartz', '2000/2004', 'Too many options can cause decision paralysis and lower satisfaction.', 'Curate, recommend and filter.', 'Are option sets manageable or supported by filters and recommendations?')
B('hyperbolic-discounting', 'Hyperbolic discounting / present bias', 'G. Ainslie; D. Laibson', '1975/1997', 'People prefer smaller immediate rewards over larger later rewards.', 'Immediate value in onboarding matters; "buy now, pay later" exploits present bias.', 'Is the immediate cost of deferred payment options made clear?')
B('planning-fallacy', 'Planning fallacy', 'D. Kahneman & A. Tversky', 1979, 'People underestimate the time needed to complete tasks.', 'Show realistic time estimates for forms and setup ("about 10 minutes").', 'Do long tasks show realistic time estimates?')
B('optimism', 'Optimism bias', 'N. Weinstein', 1980, 'People believe they are less likely than others to experience negative events.', 'Users skip backups, security settings and insurance; make protective defaults automatic.', 'Are protective behaviors (backups, 2FA, autosave) on by default?')
B('overconfidence', 'Overconfidence effect', 'S. Lichtenstein, B. Fischhoff & L. Phillips', 1982, 'Subjective confidence exceeds objective accuracy.', 'Users skip review steps; show summaries before irreversible submission.', 'Is there a review step before irreversible submissions?')
B('dunning-kruger', 'Dunning–Kruger effect', 'J. Kruger & D. Dunning', 1999, 'People with low ability in a domain overestimate their competence.', 'Self-rated skill in onboarding questionnaires is unreliable; infer from behavior.', 'Does personalization rely on behavior rather than self-rated expertise alone?', conf='medium')
B('curse-of-knowledge', 'Curse of knowledge', 'C. Camerer, G. Loewenstein & M. Weber', 1989, 'Experts find it hard to imagine not knowing what they know.', 'Teams write jargon and skip steps obvious to them; test copy with real users.', 'Has copy been tested with people outside the team?', sub='Research bias')
B('false-consensus', 'False consensus effect', 'L. Ross, D. Greene & P. House', 1977, 'People overestimate how much others share their beliefs and behaviors.', 'Designers assume users behave like them; research with real users.', 'Are design decisions based on research with actual users rather than team preference?', sub='Research bias')
B('ikea', 'IKEA effect', 'M. Norton, D. Mochon & D. Ariely', 2012, 'Higher value placed on self-assembled things.', 'Customization increases attachment.', 'Is user-created content portable?')
B('peak-end', 'Peak–end rule', 'D. Kahneman et al.', 1993, 'Experiences are remembered by peak and end.', 'Design endings and peak moments.', 'Are journey endings positive and clear?')
B('serial-position', 'Serial position effect', 'B. Murdock', 1962, 'First and last items are remembered best.', 'Place key items at start/end of lists.', 'Are key items first or last?')
B('von-restorff', 'Isolation (Von Restorff) effect', 'H. von Restorff', 1933, 'Distinct items are remembered.', 'Make primary actions distinct.', 'Is the primary action visually distinct?')
B('zeigarnik', 'Zeigarnik effect', 'B. Zeigarnik', 1927, 'Incomplete tasks are remembered better.', 'Progress and checklists motivate completion.', 'Is incompleteness used honestly?')
B('goal-gradient', 'Goal-gradient effect', 'C. Hull', 1932, 'Effort increases near the goal.', 'Show progress.', 'Do flows show progress?')
B('labor-illusion', 'Labor illusion', 'R. Buell & M. Norton', 2011, 'Visible effort increases perceived value.', 'Show meaningful work during waits.', 'Do waits show meaningful progress?')
B('mere-exposure', 'Mere-exposure effect', 'R. Zajonc', 1968, 'Familiarity breeds liking.', 'Follow conventions; brand consistency builds trust.', 'Are conventions followed?')
B('halo', 'Halo effect', 'E. Thorndike', 1920, 'One positive trait influences overall judgment.', 'Visual polish raises credibility.', 'Are there visible quality flaws?')
B('aesthetic-usability', 'Aesthetic–usability effect', 'M. Kurosu & K. Kashimura', 1995, 'Attractive designs are perceived as more usable.', 'Polish can mask problems in testing.', 'Are performance metrics measured, not just opinions?')
B('framing-price', 'Price partitioning / drip pricing', 'V. Morwitz, E. Greenleaf & E. Johnson', 1998, 'Splitting a price into base price and surcharges lowers perceived total cost.', 'Hidden fees revealed late (drip pricing) are deceptive and regulated (e.g., FTC junk fees rule 2024).', 'Is the total price, including mandatory fees, shown upfront?')
B('pain-of-paying', 'Pain of paying / payment decoupling', 'D. Prelec & G. Loewenstein', 1998, 'Paying causes psychological pain, reduced when payment is decoupled from consumption (credit, stored cards, subscriptions).', 'One-click purchase and auto-renewal reduce friction; ensure transparency and easy cancellation.', 'Are recurring charges clearly disclosed and easy to cancel?')
B('mental-accounting', 'Mental accounting', 'R. Thaler', 1985, 'People treat money differently depending on its source or intended use.', 'Credits, points and in-app currencies obscure real cost; show real-money equivalents.', 'Are virtual currencies accompanied by real-money prices?')
B('zero-price', 'Zero price effect', 'K. Shampanier, N. Mazar & D. Ariely', 2007, '"Free" is perceived as disproportionately valuable compared to a low price.', 'Free tiers and free shipping thresholds strongly influence behavior; "free" must not hide costs or data trade-offs.', 'Do "free" offers disclose conditions (auto-renewal, data use)?')
B('compromise', 'Compromise effect', 'I. Simonson', 1989, 'People tend to choose middle options.', 'Middle tiers in pricing are often chosen; place the best-fit option for most users there honestly.', 'Is the middle/recommended tier genuinely the best fit for most users?')
B('social-norms', 'Social norms effect', 'R. Cialdini, C. Kallgren & R. Reno', 1991, 'Descriptive norms ("most people do X") influence behavior.', 'Norm messages can encourage beneficial behaviors (e.g., saving, security).', 'Are norm messages truthful?')
B('herd', 'Herd behavior / information cascades', 'S. Bikhchandani, D. Hirshleifer & I. Welch', 1992, 'People follow earlier choices of others, ignoring their own information.', 'Bestseller labels and trending lists create cascades.', 'Are popularity labels based on real data?')
B('reactance', 'Psychological reactance', 'J. Brehm', 1966, 'When freedom is threatened, people resist and do the opposite.', 'Heavy-handed prompts, forced actions and nagging cause backlash; give choice.', 'Do prompts respect user choice (dismissible, not repeated after decline)?')
B('choice-supportive', 'Choice-supportive bias', 'M. Mather & M. Johnson', 2000, 'People retroactively ascribe positive attributes to options they chose.', 'Post-purchase confirmation reinforces satisfaction.', 'Do confirmation screens reinforce what the user gains?', conf='medium')
B('post-purchase', 'Post-purchase rationalization / buyer’s remorse', 'L. Festinger (cognitive dissonance)', 1957, 'After a choice, people reduce dissonance by justifying it; or experience remorse.', 'Clear confirmations, easy returns and onboarding after purchase reduce remorse.', 'Is post-purchase communication reassuring and are returns easy?')
B('cognitive-dissonance', 'Cognitive dissonance', 'L. Festinger', 1957, 'Discomfort from holding conflicting beliefs or behaviors.', 'Interfaces that contradict users’ intentions (e.g., keep promoting after cancellation) create frustration.', 'Does the product respect stated user preferences consistently?')
B('hindsight', 'Hindsight bias', 'B. Fischhoff', 1975, 'After an outcome, people believe it was predictable.', 'Post-launch analysis can be distorted; record hypotheses before tests.', 'Are experiment hypotheses recorded before results?', sub='Research bias')
B('survivorship', 'Survivorship bias', 'A. Wald (WWII aircraft analysis)', 1943, 'Focusing on successes that survived a selection process while ignoring failures.', 'Analytics of retained users ignores those who abandoned; research churned users and drop-offs.', 'Does research include users who abandoned or churned?', sub='Research bias')
B('observer-expectancy', 'Observer-expectancy effect', 'R. Rosenthal', 1966, 'Researchers’ expectations subtly influence participants.', 'Moderators must avoid leading questions and cues.', 'Are usability test scripts neutral and non-leading?', sub='Research bias')
